```cpp
#include <iostream>
using namespace std;

int main() {
    int n = 8;
    int a = 0, b = 1, c;
    for(int i = 0; i < n; i++) {
        if(i == 0) {
            cout << a << ", ";
            continue;
        }
        if(i == 1) {
            cout << b << ", ";
            continue;
        }
        c = a + b;
        a = b;
        b = c;
        cout << c;
        if(i < n - 1) cout << ", ";
    }
    return 0;
}
```

