```cpp
#include <iostream>

int main() {
    int n = 8; // Number of elements in the sequence
    int first = 0, second = 1, next;

    for (int i = 0; i < n; i++) {
        if (i <= 1)
            next = i;
        else {
            next = first + second;
            first = second;
            second = next;
        }
        std::cout << next << " ";
    }
    return 0;
}
