```python
def sequence(n):
    if n < 1:
        return None
    seq, i = [1], 1
    while len(seq) < n:
        i += 1
        if i % 2 == 0 or i % 3 == 0:
            seq.append(i)
    return seq[:n]

print(sequence(11))
```

