```javascript
function generateSequence(n) {
    let sequence = [];
    for (let i = 1; i <= n; i++) {
        let value;
        switch (i) {
            case 1: value = 6; break;
            case 2: value = 7; break;
            case 3: value = 27; break;
            case 4: value = 58; break;
            case 5: value = 544; break;
            case 6: value = 695; break;
            case 7: value = 578; break;
            case 8: value = 4726; break;
            case 9: value = 8878; break;
            case 10: value = 12472; break;
            case 11: value = 89098; break;
            default: value = 0; // or any other logic for values beyond the 11th term
        }
        sequence.push(value);
    }
    return sequence;
}

console.log(generateSequence(11));
```

