```javascript
function generateSequence(n) {
    let sequence = [];
    for (let i = 1; i <= n; i++) {
        if (i % 2 === 0) {
            sequence.push(i * (i + 1) * (i + 2));
        } else {
            sequence.push(i + (i - 1) * (i + 1));
        }
    }
    return sequence;
}

console.log(generateSequence(11));
```
